import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Home from './components/Home';
import Army from './pages/Army';
import Navy from './pages/Navy';
import Marines from './pages/Marines';
import AirForce from './pages/AirForce';
import Login from './pages/Login';
import About from './pages/About';
import Register from './components/Register';
import LandingPage from './components/LandingPage';
import Navbar from './components/Navbar';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    return localStorage.getItem('isLoggedIn') === 'true';
  });

  const handleLogout = () => {
    setIsLoggedIn(false);
    localStorage.removeItem('isLoggedIn'); // Remove login status from localStorage
    localStorage.removeItem('authToken');
  };

  return (
    <Router>
      <ConditionalNavbar isLoggedIn={isLoggedIn} handleLogout={handleLogout} />
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/home" element={<Home isLoggedIn={isLoggedIn} handleLogout={handleLogout} />} />
        <Route path="/army" element={<Army />} />
        <Route path='/navy' element={<Navy />} />
        <Route path='/marines' element={<Marines />} />
        <Route path='/air-force' element={<AirForce />} />
        <Route path='/login' element={<Login setIsLoggedIn={setIsLoggedIn} />} />
        <Route path='/about' element={<About />} />
        <Route path='/register' element={<Register />} />
      </Routes>
    </Router>
  );
}

const ConditionalNavbar = ({ isLoggedIn, handleLogout }) => {
  const location = useLocation(); // Get the current route

  // Paths where the Navbar should be hidden
  const hideNavbarOnPaths = ['/login', '/register'];

  // Show Navbar unless the current route is in the hide list
  return !hideNavbarOnPaths.includes(location.pathname) ? (
    <Navbar isLoggedIn={isLoggedIn} handleLogout={handleLogout} />
  ) : null;
}

export default App;
